// === Tab: mySketch ===
// by SamuelYAN
// more works //
   // https://twitter.com/SamuelAnn0924
   // https://www.instagram.com/samuel_yan_1990/

let colors = [];
let seed = Math.random()*10000;

function setup() {
	randomSeed(seed);
	noiseSeed(seed);
  //frameRate(1);
  // pixelDensity(5);
  let mySize = max(windowWidth, windowHeight);
  createCanvas(mySize, mySize);
  colorMode(HSB, 360, 100, 100, 100);
  background(0, 0, 5, 100);
  colors[0] = color(0, 0, 5, random(80, 50));
  colors[1] = color(0, 0, 95, random(100, 90));
  colors[2] = color(160, 80, 75, random(80, 50));
}

function draw() {
	randomSeed(seed);
  background(0, 0, 5, 100);
  creativeLine();
 noLoop();
}

function creativeLine() {
  let lineNum = random(height / 10 , height / 20);

  noFill();

  for (let i = 1; i < lineNum * 2; i += random()) {
    let offset = random(-2 * width, 2 * width);
    strokeCap(SQUARE);
    strokeWeight(random(500));
    //rotate(PI / 3);
    gradientLine(
      (i / lineNum) * random(width) + offset,
      (height / lineNum) * i,
      width - (i / lineNum) * random(width) - offset,
      (height / lineNum) * i,
      random(colors),
      random(colors)
    );
  }
}

function gradientLine(x1, y1, x2, y2, color1, color2) {
  // linear gradient from start to end of line
  // color from color1 to color2
  var grad = this.drawingContext.createLinearGradient(x1, y1, x2, y2);
  grad.addColorStop(0, color1);
  grad.addColorStop(1, color2);

  this.drawingContext.strokeStyle = grad;

  drawingContext.setLineDash([
    random(random(0.5) * sin(x1 / x2) + random(1,10) / 0.025),
    random(random(5, 100) * cos(y1 / y2) - random(1,10) / 200),
  ]);
 line(x1, y1, x2, y2);
}

function mouseClicked(){
	seed = Math.random()*10000;
  background(0, 0, 5, 100);
	loop();
}

function keyTyped() {
  if (key === "s" || key === "S") {
    noLoop();
    saveCanvas("DotandDashLine-PianoKeyboard", "png");
  }
}

